import json
import os
import secrets
import time
import uuid
import urllib.error
import urllib.request
from http.cookies import CookieError, SimpleCookie

op = urllib.request.build_opener(urllib.request.ProxyHandler({}))


def request(target, path, payload=None, cookie=None, timeout=5, expected=200):
    headers = {"User-Agent": "Pymentor-release-check", "Origin": target}
    if payload is not None:
        headers["Content-Type"] = "application/json"
    if path == "/api/user/login":
        headers["Idempotency-Key"] = str(uuid.uuid4())
    if cookie:
        headers["Cookie"] = cookie
    req = urllib.request.Request(target + path, data=None if payload is None else json.dumps(payload).encode(), headers=headers)
    started = time.monotonic()
    try:
        with op.open(req, timeout=timeout) as response:
            status, body, response_headers = response.status, response.read(200000), response.headers
    except urllib.error.HTTPError as exc:
        status, body, response_headers = exc.code, b"", exc.headers
    except Exception:
        raise SystemExit("Release check request failed") from None
    if status != expected:
        raise SystemExit("Release check HTTP status mismatch")
    if time.monotonic() - started > timeout:
        raise SystemExit("Release check latency limit")
    return body, response_headers


def candidate(target):
    nonce = secrets.token_hex(16)
    email = "preview-" + nonce + "@example.invalid"
    password = secrets.token_urlsafe(24)
    request(target, "/api/user/register", {"username": "preview-" + nonce[:16], "email": email, "password": password})
    _, headers = request(target, "/api/user/login", {"email": email, "password": password})
    cookies = SimpleCookie()
    try:
        for header in headers.get_all("Set-Cookie", []):
            cookies.load(header)
    except CookieError:
        raise SystemExit("Release check login cookie invalid") from None
    if not cookies:
        raise SystemExit("Release check login cookie missing")
    cookie = "; ".join(morsel.OutputString().split(";", 1)[0] for morsel in cookies.values())
    body, _ = request(target, "/api/learning/lessons", cookie=cookie)
    try:
        lessons = json.loads(body)["lessons"]
        task = next(task for lesson in lessons if lesson.get("is_available") for task in lesson.get("tasks", []) if task.get("id") == "lesson-fa2f4f9cd78e77a18fb1778e-task-01")
        revision = task["revision"]
        if not isinstance(revision, str) or len(revision) != 64 or any(c not in "0123456789abcdef" for c in revision):
            raise ValueError()
    except (ValueError, TypeError, KeyError, StopIteration, AttributeError):
        raise SystemExit("Release check task metadata invalid") from None
    marker = "preview_" + secrets.token_hex(16)
    body, _ = request(target, "/api/learning/tasks/lesson-fa2f4f9cd78e77a18fb1778e-task-01/run", {"code": "print(" + repr(marker) + ")", "task_revision": revision}, cookie=cookie, timeout=20)
    try:
        result = json.loads(body)
        if result.get("ok") is not True or result.get("stdout", "").strip() != marker:
            raise ValueError()
    except (ValueError, TypeError, AttributeError):
        raise SystemExit("Release check runner result invalid") from None


def main():
    kind, target, mode = (os.environ[key] for key in ("CHECK_KIND", "CHECK_TARGET", "CHECK_MODE"))
    paths = ["/health/ready", "/api/learning/catalog", "/api/user/me"] if kind == "core-api" else ["/", "/index.html"]
    if mode == "live":
        paths = (["/health/ready"] if kind == "core-api" else ["/"]) * 20
    for path in paths:
        request(target, path, expected=401 if path == "/api/user/me" else 200)
        if mode == "live":
            time.sleep(.15)
    if kind == "core-api" and mode == "candidate":
        candidate(target)
    print("release checks passed", len(paths), kind, mode)


if __name__ == "__main__":
    main()
